// ── Hexagonal: define ports as interfaces (JS duck-typed) ────────

// PORT (what the domain expects from outside)
function createOrderService(orderRepo, emailSender) {
  return {
    placeOrder(customerId, items) {
      const total = items.reduce((s, i) => s + i.price, 0);
      const order = { customerId, items, total, status: 'placed' };
      orderRepo.save(order);                    // port: save
      emailSender.send(customerId, 'Order placed!'); // port: send
      return order;
    }
  };
}

// ADAPTER (in-memory, used in tests)
const inMemoryOrderRepo = { orders: [], save(o) { this.orders.push(o); } };
const consolEmailSender = { send: (to, msg) => console.log(`[Email] to=${to}: ${msg}`) };

// ADAPTER (real, used in production)
// const pgOrderRepo    = { save: (o) => db.query('INSERT INTO orders...', o) };
// const sesEmailSender = { send: (to, msg) => aws.ses.send({ to, msg }) };

// Same domain logic, swappable adapters
const service = createOrderService(inMemoryOrderRepo, consolEmailSender);
const order = service.placeOrder('cust-1', [{ price: 49 }, { price: 29 }]);
console.log('Order total:', order.total); // 78
console.log('Saved orders:', inMemoryOrderRepo.orders.length); // 1

// ── Event-Driven: publish / subscribe decoupling ─────────────────
const EventBus = {
  _handlers: {},
  on(event, fn)   { (this._handlers[event] = this._handlers[event] || []).push(fn); },
  emit(event, data) { (this._handlers[event] || []).forEach(fn => fn(data)); }
};

// Producer — knows nothing about consumers
function placeOrder(order) {
  console.log('Order placed:', order.id);
  EventBus.emit('OrderPlaced', order);
}

// Consumers — know nothing about each other
EventBus.on('OrderPlaced', (o) => console.log(`[Inventory] reserve stock for order ${o.id}`));
EventBus.on('OrderPlaced', (o) => console.log(`[Email] send confirmation to ${o.customerId}`));
EventBus.on('OrderPlaced', (o) => console.log(`[Analytics] log conversion for ${o.id}`));

placeOrder({ id: 'ord-42', customerId: 'cust-1', total: 78 });

// ── Bounded Context: same word, different model ──────────────────
// In Billing context, 'Product' has price and tax category
const BillingProduct = (id, price, taxCategory) => ({ id, price, taxCategory });

// In Inventory context, 'Product' has stock and warehouse location
const InventoryProduct = (id, sku, warehouseLocation, stockLevel) =>
  ({ id, sku, warehouseLocation, stockLevel });

// These are DIFFERENT models in DIFFERENT contexts — deliberately.
// An anti-corruption layer translates between them when contexts communicate:
function billingProductFromCatalog(catalogProduct) {
  return BillingProduct(catalogProduct.id, catalogProduct.listPrice, catalogProduct.taxCode);
}

// ── Layered: strict dependency direction ─────────────────────────
// presentation → service (business logic) → repository (data)
class UserRepository {
  findById(id) { return { id, name: 'Alice', email: 'alice@example.com' }; } // simulated DB
}
class UserService {
  constructor(repo) { this._repo = repo; }
  getProfile(id)   { return this._repo.findById(id); } // no HTTP, no DB driver here
}
// controller (presentation layer) — knows HTTP, delegates to service
function handleGetUser(req, res, service) {
  const user = service.getProfile(req.params.id);
  res.json(user); // simulated response
}
// Each layer only imports the one below it — presentation never touches the repository directly.
const repo    = new UserRepository();
const svc     = new UserService(repo);
const fakeRes = { json: (d) => console.log('Response:', d) };
handleGetUser({ params: { id: 1 } }, fakeRes, svc);
// Response: { id: 1, name: 'Alice', email: 'alice@example.com' }
